fn parse<I, O>(&self, rawargs: I, args: &mut LowArgs) -> anyhow::Result<()>
where
    I: IntoIterator<Item = O>,
    O: Into<OsString>,
{
    let mut it = rawargs.into_iter();

    while let Some(arg) = it.next() {
        let arg = arg.into::<OsString>();
        let arg = arg.to_string();
        if arg.starts_with('-') {
            if arg == "--" {
                // End of options
                break;
            } else if arg.starts_with("--no-") {
                // Negation
                let flag = &arg[6..];
                let FlagLookup::Match(info) = self.find_long(flag) else {
                    return Err(anyhow::anyhow::Error::msg(format!(
                        "unrecognized flag: {}. {}",
                        arg,
                        suggest(flag).unwrap_or("No similar flags available.")
                    )));
                };
                if info.kind != FlagInfoKind::Standard {
                    return Err(anyhow::anyhow::Error::msg(format!(
                        "flag {arg} is not a standard flag",
                    )));
                }
                let name = &info.name;
                set_flag(name, FlagValue::Switch(false), args)?;
            } else if arg.starts_with("--") {
